package com.bank.status;

import com.bank.status.gen.*;
import com.google.protobuf.Any;
import com.google.rpc.BadRequest;
import com.google.rpc.Code;
import com.google.rpc.ErrorInfo;
import io.grpc.protobuf.StatusProto;
import io.grpc.stub.StreamObserver;
import java.math.BigDecimal;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class TransferServiceImpl extends TransferServiceGrpc.TransferServiceImplBase {
    private static final Logger log = Logger.getLogger(TransferServiceImpl.class.getName());
    private final Map<String, BigDecimal> balances = new ConcurrentHashMap<>(Map.of(
        "SAV2001", new BigDecimal("1000000"),   // Rajesh
        "CUR3001", new BigDecimal("250000")));    // Priya

    @Override
    public void transfer(TransferRequest req, StreamObserver<TransferResponse> obs) {
        // INVALID_ARGUMENT (→ HTTP 400) with BadRequest field violation details
        BigDecimal amount;
        try {
            amount = new BigDecimal(req.getAmount());
        } catch (NumberFormatException e) {
            obs.onError(badRequest("amount", "must be a valid number"));
            return;
        }
        if (amount.signum() <= 0) {
            obs.onError(badRequest("amount", "must be greater than zero"));
            return;
        }
        // NOT_FOUND (→ HTTP 404)
        if (!balances.containsKey(req.getFromAccount())) {
            log.warning(() -> "Account not found: " + req.getFromAccount());
            obs.onError(io.grpc.Status.NOT_FOUND
                .withDescription("account " + req.getFromAccount() + " not found")
                .asRuntimeException());
            return;
        }
        // FAILED_PRECONDITION (→ HTTP 400) with ErrorInfo structured metadata
        BigDecimal from = balances.get(req.getFromAccount());
        if (from.compareTo(amount) < 0) {
            com.google.rpc.Status rich = com.google.rpc.Status.newBuilder()
                .setCode(Code.FAILED_PRECONDITION_VALUE)
                .setMessage("insufficient funds")
                .addDetails(Any.pack(ErrorInfo.newBuilder()
                    .setReason("INSUFFICIENT_FUNDS")
                    .setDomain("nbi.bank")
                    .putMetadata("available", from.toString())
                    .putMetadata("requested", amount.toString())
                    .build()))
                .build();
            obs.onError(StatusProto.toStatusRuntimeException(rich));
            return;
        }
        // OK (→ HTTP 200)
        balances.put(req.getFromAccount(), from.subtract(amount));
        balances.merge(req.getToAccount(), amount, BigDecimal::add);
        obs.onNext(TransferResponse.newBuilder()
            .setTransferId("TXF-" + UUID.randomUUID()).setStatus("COMPLETED").build());
        obs.onCompleted();
    }

    // Build INVALID_ARGUMENT with a BadRequest field-violation detail.
    private io.grpc.StatusRuntimeException badRequest(String field, String desc) {
        com.google.rpc.Status rich = com.google.rpc.Status.newBuilder()
            .setCode(Code.INVALID_ARGUMENT_VALUE)
            .setMessage("validation failed")
            .addDetails(Any.pack(BadRequest.newBuilder()
                .addFieldViolations(BadRequest.FieldViolation.newBuilder()
                    .setField(field).setDescription(desc).build())
                .build()))
            .build();
        return StatusProto.toStatusRuntimeException(rich);
    }
}
