package com.bank.status;

import com.bank.status.gen.*;
import com.google.rpc.BadRequest;
import com.google.rpc.ErrorInfo;
import com.google.protobuf.Any;
import io.grpc.*;
import io.grpc.protobuf.StatusProto;
import java.util.logging.Logger;

public class TransferClient {
    private static final Logger log = Logger.getLogger(TransferClient.class.getName());
    public static void main(String[] args) {
        ManagedChannel channel = ManagedChannelBuilder
            .forAddress("localhost", 9090).usePlaintext().build();
        TransferServiceGrpc.TransferServiceBlockingStub stub =
            TransferServiceGrpc.newBlockingStub(channel);
        try {
            stub.transfer(TransferRequest.newBuilder()
                .setFromAccount("SAV2001").setToAccount("CUR3001")
                .setAmount("5000000").build());     // more than Rajesh has → FAILED_PRECONDITION
        } catch (StatusRuntimeException e) {
            log.warning(() -> "code=" + e.getStatus().getCode() + " msg=" + e.getStatus().getDescription());
            com.google.rpc.Status rich = StatusProto.fromThrowable(e);   // parse rich details
            if (rich != null) {
                for (Any d : rich.getDetailsList()) {
                    if (d.is(ErrorInfo.class)) {
                        try {
                            ErrorInfo info = d.unpack(ErrorInfo.class);
                            log.info("reason=" + info.getReason() + " meta=" + info.getMetadataMap());
                        } catch (Exception ignore) { }
                    } else if (d.is(BadRequest.class)) {
                        try {
                            BadRequest br = d.unpack(BadRequest.class);
                            br.getFieldViolationsList().forEach(v ->
                                log.info("field=" + v.getField() + " -> " + v.getDescription()));
                        } catch (Exception ignore) { }
                    }
                }
            }
        }
        channel.shutdown();
    }
}
